account_invoice_obj = pool['account.invoice']
#pdb.set_trace()
from_date =  (datetime.date.today()).strftime('%Y-%m-01 00:00:00')
to_date = (datetime.date.today() + dateutil.relativedelta.relativedelta(months=1)).strftime('%Y-%m-01 00:00:00')
fatturato = {}
account_invoice_ids = account_invoice_obj.search(cr, uid, [('date_invoice', '>', from_date), ('date_invoice', '<', to_date), ('state', 'not in', ['draft', 'cancel']), ('type', 'in', ['out_invoice', 'out_refund'])], context=context)

fatturato_totale = 0.0

for fattura in account_invoice_obj.browse(cr, uid, account_invoice_ids, context):
    if fattura.type == 'out_invoice':
        sign = 1
    else:
        sign = -1
    if fatturato.get(fattura.partner_id.name):
        fatturato[fattura.partner_id.name]['amount_total'] += sign * fattura.amount_total
    else:
        fatturato.update({fattura.partner_id.name: {'amount_total': sign * fattura.amount_total}})

    fatturato_totale += sign * fattura.amount_total

if fatturato == {}:
    fatturato = {'NESSUNA VENDITA': {'amount_total': 0}}
data['from_date'] = from_date
data['to_date'] = to_date
data['fatturato'] = OrderedDict(sorted(fatturato.items(), key=lambda t: t[0]))
data['fatturato_totale'] = fatturato_totale

account_invoice_obj = pool['account.invoice']
#pdb.set_trace()
from_date =  (datetime.date.today() - dateutil.relativedelta.relativedelta(months=1)).strftime('%Y-%m-01 00:00:00')
to_date = datetime.date.today().strftime('%Y-%m-01 00:00:00')
fatturato = {}
account_invoice_ids = account_invoice_obj.search(cr, uid, [('date_invoice', '>', from_date), ('date_invoice', '<', to_date), ('state', 'not in', ['draft', 'cancel']), ('type', 'in', ['out_invoice', 'out_refund'])], context=context)

fatturato_totale = 0.0

for fattura in account_invoice_obj.browse(cr, uid, account_invoice_ids, context):
    if fatturato.get(fattura.partner_id.name):
        fatturato[fattura.partner_id.name]['amount_total'] += fattura.amount_total
    else:
        fatturato.update({fattura.partner_id.name: {'amount_total': fattura.amount_total}})

    fatturato_totale += fattura.amount_total

if fatturato == {}:
    fatturato = {'NESSUNA VENDITA': {'amount_total': 0}}
data['from_date'] = from_date
data['to_date'] = to_date
data['fatturato'] = OrderedDict(sorted(fatturato.items(), key=lambda t: t[0]))
data['fatturato_totale'] = fatturato_totale

